def source_link(path, symbol):
    lines=(ROOT/path).read_text(encoding="utf-8").splitlines()
    line=1
    if symbol:
        pattern=re.compile(r"^(?:def|class) "+re.escape(symbol)+r"\b")
        line=next((i for i,text in enumerate(lines,1) if pattern.search(text)),None)
        if line is None:
            raise ValueError(f"Missing repository reference: {path}::{symbol}")
    return path,line,symbol

